    stock = dict(data['stock'])
    shipped = {sku: 0 for sku in stock}
    reservations = {}
    used_ids = set()
    log = []

    def expire_expired():
        for hold in list(reservations.values()):
            if hold['status'] == 'active' and hold['expires'] <= t:
                hold['status'] = 'expired'
                for sku, qty in hold['left'].items():
                    stock[sku] += qty
                    hold['left'][sku] = 0

    for event in data['events']:
        t = event['t']
        expire_expired()
        op = event['op']

        if op == 'restock':
            for sku, qty in event['items'].items():
                stock[sku] += qty
            log.append('restocked')
            continue

        ident = event['id']
        if op == 'reserve':
            if ident in used_ids:
                log.append('duplicate')
                continue
            possible = True
            for sku, qty in event['items'].items():
                if qty > stock[sku]:
                    possible = False
                    break
            if not possible:
                log.append('insufficient')
                continue
            for sku, qty in event['items'].items():
                stock[sku] -= qty
            reservations[ident] = {'status': 'active', 'expires': event['expires'], 'left': dict(event['items'])}
            used_ids.add(ident)
            log.append('reserved')
            continue

        hold = reservations.get(ident)
        if hold is None or hold['status'] != 'active':
            log.append('inactive')
            continue

        if op == 'cancel':
            hold['status'] = 'cancelled'
            for sku, qty in hold['left'].items():
                stock[sku] += qty
                hold['left'][sku] = 0
            log.append('cancelled')
            continue

        possible = True
        for sku, qty in event['items'].items():
            if qty > hold['left'].get(sku, 0):
                possible = False
                break
        if not possible:
            log.append('exceeds')
            continue

        for sku, qty in event['items'].items():
            hold['left'][sku] -= qty
            shipped[sku] += qty
            stock[sku] += qty

        if all(q == 0 for q in hold['left'].values()):
            hold['status'] = 'completed'
        log.append('fulfilled')

    expire_expired()

    result = []
    for ident in sorted(reservations.keys()):
        hold = reservations[ident]
        if hold['status'] == 'active':
            remaining = dict(hold['left'])
        else:
            remaining = {sku: 0 for sku in hold['left']}
        result.append({'id': ident, 'status': hold['status'], 'remaining': remaining})

    inventory = []
    for sku in sorted(stock.keys()):
        held = sum(h['left'].get(sku, 0) for h in reservations.values() if h['status'] == 'active')
        inventory.append({'sku': sku, 'available': stock[sku], 'reserved': held, 'shipped': shipped[sku]})

    return {'log': log, 'inventory': inventory, 'reservations': result}
